"""
Deep health check endpoint.

Probes every external service that is configured via environment variables
(CHAT_API_BASE_URL, OPENCLAW_API_URL, HERMES_API_URL) and returns a summary
status plus per-service detail.

Response shape:
    {
        "status": "ok" | "degraded" | "down",
        "services": {"<name>": "ok" | "error", ...}
    }

"ok"      - all configured services responded (any HTTP status counts)
"degraded" - some services are reachable, some are not
"down"    - no configured services are reachable (or none are configured)
"""

import asyncio
import os
from typing import Literal

import httpx
from fastapi import APIRouter

router = APIRouter(prefix="/health", tags=["health"])

_PROBE_TIMEOUT = httpx.Timeout(3.0, connect=2.0)


def _configured_services() -> dict[str, str]:
    """Return {service_name: base_url} for every service present in env."""
    candidates: dict[str, str] = {
        "chat_api": os.getenv("CHAT_API_BASE_URL", "").strip(),
        "openclaw": os.getenv("OPENCLAW_API_URL", "").strip(),
        "hermes": os.getenv("HERMES_API_URL", "").strip(),
    }
    return {name: url for name, url in candidates.items() if url}


def _base_url(raw: str) -> str:
    """Strip well-known API path suffixes so we probe the root."""
    for suffix in ("/v1/chat/completions", "/v1", "/chat/completions"):
        if raw.endswith(suffix):
            raw = raw[: -len(suffix)]
    return raw.rstrip("/") + "/"


async def _probe(client: httpx.AsyncClient, name: str, raw_url: str) -> tuple[str, str]:
    """Return (name, "ok" | "error"). Any HTTP response counts as ok."""
    try:
        await client.get(_base_url(raw_url), follow_redirects=True)
        return name, "ok"
    except Exception:
        return name, "error"


@router.get("/deep")
async def health_deep():
    """Probe all configured external services and report aggregate health."""
    services_urls = _configured_services()

    if not services_urls:
        return {"status": "ok", "services": {}}

    async with httpx.AsyncClient(timeout=_PROBE_TIMEOUT) as client:
        results = await asyncio.gather(
            *[_probe(client, name, url) for name, url in services_urls.items()]
        )

    services: dict[str, str] = dict(results)
    ok_count = sum(1 for s in services.values() if s == "ok")
    total = len(services)

    if ok_count == total:
        overall: Literal["ok", "degraded", "down"] = "ok"
    elif ok_count == 0:
        overall = "down"
    else:
        overall = "degraded"

    return {"status": overall, "services": services}

